<?php
namespace Tests\Feature;
use Tests\TestCase;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\{Http,DB};
use App\Models\{User,AiConnection};
class MarketingPostAiTest extends TestCase {
 use RefreshDatabase;
 public function test_ai_connect_quote_requires_confirmation_and_never_repeats_transport(){ $this->travelTo(\Carbon\Carbon::parse('2026-10-28'));Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);AiConnection::create(['provider'=>'openai','enabled'=>true,'verified_at'=>now(),'text_model'=>'gpt-6-luna','api_key'=>'SECRET','base_url'=>'https://api.openai.com/v1','version'=>1]);$input=['copy'=>'Original','targets'=>[],'context'=>['source'=>'topic','subject'=>'Store update','facts'=>'Open on Saturday.','language'=>'English','tone'=>'Friendly','purpose'=>'Brand awareness','audience'=>'Customers'],'action'=>'draft'];$q=$this->postJson('/admin/marketing/posts/ai/quote',$input)->assertOk()->assertDontSee('SECRET')->json();Http::assertNothingSent();$this->postJson('/admin/marketing/posts/ai/generate',['id'=>$q['id'],'approved'=>false])->assertUnprocessable();Http::fake(['api.openai.com/*'=>Http::response(['status'=>'completed','usage'=>['input_tokens'=>200,'output_tokens'=>100],'output'=>[['content'=>[['type'=>'output_text','text'=>json_encode(['suggestions'=>[['target'=>'shared','text'=>'Visit us on Saturday.','used_fact_ids'=>['f1']]],'notes'=>[]])]]]]])]);$this->postJson('/admin/marketing/posts/ai/generate',['id'=>$q['id'],'approved'=>true])->assertOk()->assertJsonPath('suggestions.0.text','Visit us on Saturday.');$this->postJson('/admin/marketing/posts/ai/generate',['id'=>$q['id'],'approved'=>true])->assertOk();Http::assertSentCount(1);$this->assertDatabaseCount('marketing_posts',0); }
 public function test_unknown_cost_blocks_new_request_and_cross_user_access(){ $this->travelTo(\Carbon\Carbon::parse('2026-10-28'));Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]);$this->actingAs($u);AiConnection::create(['provider'=>'openai','enabled'=>true,'verified_at'=>now(),'text_model'=>'gpt-6-luna','api_key'=>'SECRET','version'=>1]);$input=['copy'=>'Original','targets'=>[],'context'=>['source'=>'topic','subject'=>'Store update','facts'=>'Open Saturday','language'=>'English','tone'=>'Friendly','purpose'=>'Brand awareness','audience'=>'Customers'],'action'=>'draft'];$q=$this->postJson('/admin/marketing/posts/ai/quote',$input)->assertOk()->json();$attempts=0;Http::fake(function()use(&$attempts){$attempts++;throw new \Illuminate\Http\Client\ConnectionException('timeout');});$this->postJson('/admin/marketing/posts/ai/generate',['id'=>$q['id'],'approved'=>true])->assertUnprocessable();$this->postJson('/admin/marketing/posts/ai/generate',['id'=>$q['id'],'approved'=>true])->assertStatus(409);$this->postJson('/admin/marketing/posts/ai/quote',$input)->assertStatus(409);$this->assertSame(1,$attempts);$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->postJson('/admin/marketing/posts/ai/generate',['id'=>$q['id'],'approved'=>true])->assertNotFound();$this->assertSame(1,$attempts); }
 public function test_edit_permission_alone_cannot_approve_paid_generation(){Http::preventStrayRequests();$u=User::factory()->create(['is_admin'=>true,'is_super_admin'=>false]);$u->permissions()->create(['permission'=>'marketing.view']);$u->permissions()->create(['permission'=>'marketing.edit']);$this->actingAs($u);$this->postJson('/admin/marketing/posts/ai/generate',['id'=>(string)\Illuminate\Support\Str::uuid(),'approved'=>true])->assertForbidden();Http::assertNothingSent();}
 public function test_text_quote_is_independent_of_disabled_video_billing(){ $this->travelTo(\Carbon\Carbon::parse('2026-10-28'));Http::preventStrayRequests();config(['marketing.execution_enabled'=>false,'marketing.billing.enabled'=>false,'marketing.billing.pricing_valid_until'=>'2026-10-30']);$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));AiConnection::create(['provider'=>'openai','enabled'=>true,'verified_at'=>now(),'text_model'=>'gpt-5.6-luna','api_key'=>'SECRET','version'=>1]);$this->postJson('/admin/marketing/posts/ai/quote',['copy'=>'','targets'=>[],'context'=>['source'=>'topic','subject'=>'Store update','facts'=>'Open Saturday','language'=>'English','tone'=>'Friendly','purpose'=>'Brand awareness','audience'=>'Customers'],'action'=>'draft'])->assertOk()->assertJsonPath('model','gpt-5.6-luna')->assertJsonPath('cap_microusd',6000);$this->assertFalse(config('marketing.billing.enabled'));Http::assertNothingSent(); }
 public function test_unconfigured_ai_never_calls_provider(){Http::preventStrayRequests();$this->actingAs(User::factory()->create(['is_admin'=>true,'is_super_admin'=>true]));$this->postJson('/admin/marketing/posts/ai/quote',['copy'=>'','targets'=>[],'context'=>['source'=>'topic','subject'=>'Hello','facts'=>'','language'=>'English','tone'=>'Friendly','purpose'=>'Brand awareness','audience'=>'All'],'action'=>'draft'])->assertStatus(422);Http::assertNothingSent();}
}
